html:
{#- MMG Sales Invoice: Arabic (right-to-left) when printed in Arabic, English otherwise.
    Labels are written here instead of relying on ERPNext's translations, several of which are
    missing or wrong for invoices (e.g. "Amount" and "Nos"). The amount in words is always built
    from the payable total, so it matches the figure printed next to it. -#}
{%- set ar = _("Invoice") != "Invoice" -%}
{%- set L = {
	"title": ("Sales Invoice", "فاتورة مبيعات"),
	"return": ("Credit Note", "إشعار دائن (مرتجع)"),
	"cancelled": ("CANCELLED", "ملغاة"),
	"draft": ("DRAFT", "مسودة"),
	"customer": ("Customer Name", "اسم العميل"),
	"bill_to": ("Bill To", "العنوان"),
	"branch": ("Branch", "الفرع"),
	"number": ("Invoice Number", "رقم الفاتورة"),
	"date": ("Invoice Date", "تاريخ الفاتورة"),
	"due": ("Payment Due Date", "تاريخ الاستحقاق"),
	"no": ("#", "م"),
	"item": ("Item", "الصنف"),
	"qty": ("Quantity", "الكمية"),
	"rate": ("Rate", "سعر الوحدة"),
	"amount": ("Amount", "القيمة"),
	"subtotal": ("Sub Total", "الإجمالي قبل الخصم والضرائب"),
	"discount": ("Discount", "الخصم"),
	"grand": ("Grand Total", "الإجمالي"),
	"rounded": ("Rounded Total", "الإجمالي بعد التقريب"),
	"paid": ("Paid", "المدفوع"),
	"outstanding": ("Outstanding", "المتبقي"),
	"words": ("In Words", "المبلغ بالحروف"),
	"payment": ("Payment", "الدفع"),
	"change": ("Change Given", "الباقي للعميل"),
	"terms": ("Terms and Conditions", "الشروط والأحكام"),
	"page": ("Page {0} of {1}", "صفحة {0} من {1}"),
} -%}
{%- macro t(key) -%}{{ L[key][1] if ar else L[key][0] }}{%- endmacro -%}
{%- set UOM_AR = {"Nos": "وحدة", "Unit": "وحدة", "Ream": "رزمة", "Box": "كرتونة", "Hour": "ساعة"} -%}
{%- set start = "right" if ar else "left" -%}
{%- set end = "left" if ar else "right" -%}

{#- Payable total: the rounded total when rounding is on for this invoice, otherwise the grand total. -#}
{%- set payable = doc.rounded_total if (doc.rounded_total and not doc.disable_rounded_total) else doc.grand_total -%}
{%- set pounds = (payable | abs) | int -%}
{%- set piastres = ((((payable | abs) - pounds) * 100) | round) | int -%}
{%- if ar -%}
	{%- set words = "فقط " ~ (frappe.utils.in_words(pounds) if pounds else "صفر") ~ " جنيه مصري"
		~ ((" و" ~ frappe.utils.in_words(piastres) ~ " قرشًا") if piastres else "") ~ " لا غير" -%}
{%- else -%}
	{%- set words = frappe.utils.money_in_words(payable | abs, doc.currency) -%}
{%- endif -%}

{% for page in layout %}
<div class="page-break invoice-page" dir="{{ 'rtl' if ar else 'ltr' }}">

	<style>
		.invoice-page { font-family: Inter, "DejaVu Sans", sans-serif; color: #171717; }
		.print-format-body { padding: 30px 12px 12px 12px !important; }
		.muted { color: #7c7c7c !important; }
		.doc-title { font-size: 20px; font-weight: 700; margin: 0 0 4px 0; }
		.status { color: #c0392b; font-weight: 700; margin: 8px 0; }
		.info-table { width: 100%; margin-top: 24px; border-collapse: collapse; }
		.info-table td { padding: 4px 8px !important; vertical-align: top; }
		.items-table { width: 100%; border-collapse: separate; border-spacing: 0; margin-top: 16px; }
		.items-table td { border-bottom: 1px solid #ededed; padding: 8px !important; }
		.items-table thead td { color: #7c7c7c !important; background: #f8f8f8; }
		.totals { width: 55%; border-collapse: collapse; margin-top: 16px; }
		.totals td { padding: 6px 8px !important; border-bottom: 1px solid #e9e9e9; }
		.grand { background: #f8f8f8; font-weight: 700; }
		.words { margin-top: 16px; padding: 10px 12px; background: #f8f8f8; border-radius: 8px; line-height: 1.6; }
		.terms { margin-top: 32px; }
		.clear { clear: both; }
		.head { width: 100%; border-collapse: collapse; background: #f8f8f8; }
		.head td { padding: 14px 16px !important; vertical-align: top; }
		.company-name { font-size: 16px; font-weight: 700; }
		.logo { max-height: 60px; max-width: 120px; margin-bottom: 6px; border-radius: 8px; }
	</style>

	<div class="print-format-body">
		{#- Own header instead of the site's letter head, which prints the English doctype name. -#}
		{%- set company = frappe.db.get_value("Company", doc.company, ["company_logo", "phone_no", "email"], as_dict=True) -%}
		<table class="head">
			<tr>
				<td style="text-align: {{ start }}">
					{% if company.company_logo %}<img class="logo" src="{{ frappe.utils.get_url(company.company_logo) }}"><br>{% endif %}
					<div class="company-name">{{ doc.company | e }}</div>
					{% if company.phone_no %}<div class="muted">{{ company.phone_no | e }}</div>{% endif %}
					{% if company.email %}<div class="muted">{{ company.email | e }}</div>{% endif %}
				</td>
				<td style="text-align: {{ end }}">
					<div class="doc-title">{{ t("return") if doc.is_return else t("title") }}</div>
					<div class="muted">{{ doc.name }}</div>
				</td>
			</tr>
		</table>
		{%- if doc.docstatus == 2 -%}
			<div class="status" style="text-align: {{ start }}">{{ t("cancelled") }}</div>
		{%- elif doc.docstatus == 0 and (print_settings == None or print_settings.add_draft_heading) -%}
			<div class="status" style="text-align: {{ start }}">{{ t("draft") }}</div>
		{%- endif -%}

		<table class="info-table">
			<tr>
				<td class="muted" style="text-align: {{ start }}; width: 18%">{{ t("customer") }}</td>
				<td style="text-align: {{ start }}; width: 32%">{{ doc.customer_name | e }}</td>
				<td class="muted" style="text-align: {{ start }}; width: 18%">{{ t("number") }}</td>
				<td style="text-align: {{ start }}; width: 32%">{{ doc.name }}</td>
			</tr>
			<tr>
				<td class="muted" style="text-align: {{ start }}">{{ t("branch") }}</td>
				<td style="text-align: {{ start }}">{{ ((doc.cost_center or "").rsplit(" - ", 1)[0]) | e }}</td>
				<td class="muted" style="text-align: {{ start }}">{{ t("date") }}</td>
				<td style="text-align: {{ start }}">{{ frappe.utils.format_date(doc.posting_date) }}</td>
			</tr>
			<tr>
				<td class="muted" style="text-align: {{ start }}">{% if doc.customer_address %}{{ t("bill_to") }}{% endif %}</td>
				<td style="text-align: {{ start }}">
					{%- if doc.customer_address -%}
						{%- set a = frappe.db.get_value("Address", doc.customer_address, ["address_line1", "address_line2", "city"], as_dict=True) -%}
						{{ (a.address_line1 or "") | e }}{% if a.address_line2 %}، {{ a.address_line2 | e }}{% endif %}{% if a.city %}، {{ a.city | e }}{% endif %}
					{%- endif -%}
				</td>
				<td class="muted" style="text-align: {{ start }}">{{ t("due") }}</td>
				<td style="text-align: {{ start }}">{{ frappe.utils.format_date(doc.due_date) }}</td>
			</tr>
		</table>

		<table class="items-table">
			<thead>
				<tr>
					<td style="text-align: center; width: 6%">{{ t("no") }}</td>
					<td style="text-align: {{ start }}">{{ t("item") }}</td>
					<td style="text-align: {{ end }}">{{ t("qty") }}</td>
					<td style="text-align: {{ end }}">{{ t("rate") }}</td>
					<td style="text-align: {{ end }}">{{ t("amount") }}</td>
				</tr>
			</thead>
			<tbody>
				{% for item in doc.items %}
				<tr>
					<td style="text-align: center">{{ loop.index }}</td>
					<td style="text-align: {{ start }}">{{ item.item_name | e }}</td>
					<td style="text-align: {{ end }}">{{ item.get_formatted("qty", 0) }} {{ UOM_AR.get(item.uom, item.uom) if ar else item.uom }}</td>
					<td style="text-align: {{ end }}">{{ item.get_formatted("net_rate", doc) }}</td>
					<td style="text-align: {{ end }}">{{ item.get_formatted("net_amount", doc) }}</td>
				</tr>
				{% endfor %}
			</tbody>
		</table>

		<table class="totals" style="float: {{ end }}">
			<tr>
				<td class="muted" style="text-align: {{ start }}">{{ t("subtotal") }}</td>
				<td style="text-align: {{ end }}">{{ doc.get_formatted("total", doc) }}</td>
			</tr>
			{%- if doc.discount_amount -%}
			<tr>
				<td class="muted" style="text-align: {{ start }}">{{ t("discount") }}{% if doc.additional_discount_percentage %} ({{ doc.additional_discount_percentage }}%){% endif %}</td>
				<td style="text-align: {{ end }}">- {{ doc.get_formatted("discount_amount", doc) }}</td>
			</tr>
			{%- endif -%}
			{%- for tax in doc.taxes -%}
				{%- if tax.tax_amount and (not tax.included_in_print_rate or doc.flags.show_inclusive_tax_in_print) -%}
				<tr>
					<td class="muted" style="text-align: {{ start }}">{{ tax.description | e }}{% if tax.rate %} ({{ tax.get_formatted("rate") }}%){% endif %}</td>
					<td style="text-align: {{ end }}">{{ tax.get_formatted("tax_amount") }}</td>
				</tr>
				{%- endif -%}
			{%- endfor -%}
			<tr class="grand">
				<td style="text-align: {{ start }}">{{ t("grand") }}</td>
				<td style="text-align: {{ end }}">{{ doc.get_formatted("grand_total", doc) }}</td>
			</tr>
			{%- if payable != doc.grand_total -%}
			<tr class="grand">
				<td style="text-align: {{ start }}">{{ t("rounded") }}</td>
				<td style="text-align: {{ end }}">{{ doc.get_formatted("rounded_total", doc) }}</td>
			</tr>
			{%- endif -%}
			{%- if doc.docstatus == 1 and doc.outstanding_amount != payable -%}
			<tr>
				<td class="muted" style="text-align: {{ start }}">{{ t("paid") }}</td>
				<td style="text-align: {{ end }}">{{ frappe.utils.fmt_money(payable - doc.outstanding_amount, currency=doc.currency) }}</td>
			</tr>
			<tr>
				<td class="muted" style="text-align: {{ start }}">{{ t("outstanding") }}</td>
				<td style="text-align: {{ end }}">{{ doc.get_formatted("outstanding_amount", doc) }}</td>
			</tr>
			{%- endif -%}
		</table>
		<div class="clear"></div>

		{#- How a sale at the counter was paid (the point of sale's payment methods), with the change given. -#}
		{%- set paid_by = (doc.payments | selectattr("amount") | list) if (doc.is_pos and doc.docstatus == 1) else [] -%}
		{%- if paid_by -%}
		<table class="totals payments" style="float: {{ end }}">
			<tr><td class="muted" colspan="2" style="text-align: {{ start }}">{{ t("payment") }}</td></tr>
			{%- for p in paid_by -%}
			<tr>
				<td style="text-align: {{ start }}">{{ _(p.mode_of_payment) | e }}</td>
				<td style="text-align: {{ end }}">{{ p.get_formatted("amount", doc) }}</td>
			</tr>
			{%- endfor -%}
			{%- if doc.change_amount -%}
			<tr>
				<td class="muted" style="text-align: {{ start }}">{{ t("change") }}</td>
				<td style="text-align: {{ end }}">{{ doc.get_formatted("change_amount", doc) }}</td>
			</tr>
			{%- endif -%}
		</table>
		<div class="clear"></div>
		{%- endif -%}

		<div class="words" style="text-align: {{ start }}">
			<span class="muted">{{ t("words") }}:</span> {{ words }}
		</div>

		{% if doc.terms %}
		<div class="terms" style="text-align: {{ start }}">
			<div class="muted">{{ t("terms") }}</div>
			{{ doc.terms }}
		</div>
		{% endif %}
	</div>

	<div {% if print_settings.repeat_header_footer %} id="footer-html" class="visible-pdf" {% endif %}>
		{% if not no_letterhead and footer %}
		<div class="letter-head-footer">{{ footer }}</div>
		{% endif %}
		{% if print_settings.repeat_header_footer %}
		<p class="text-center small page-number visible-pdf">
			{{ t("page").format('<span class="page"></span>', '<span class="topage"></span>') }}
		</p>
		{% endif %}
	</div>
</div>
{% endfor %}
